public class Basics {
    public static void main(String[] args) {
        // Primitives: hold the value, cannot be null.
        int count = 3;
        double rate = 0.15;

        // Objects: hold a reference, can be null.
        Integer boxed = 3;
        Integer nothing = null;

        // Autoboxing hides an unboxing call that throws on null.
        // int broken = nothing + 1;      // NullPointerException on a line that
                                          // looks like plain arithmetic

        // == on objects compares REFERENCES, not values.
        Integer a = 1000, b = 1000;
        System.out.println(a == b);        // false — two distinct objects
        System.out.println(a.equals(b));   // true  — compares values

        // Small integers are cached, so this prints true. Relying on it is a bug
        // waiting for the day a value exceeds 127.
        Integer small1 = 100, small2 = 100;
        System.out.println(small1 == small2);   // true — do not depend on this

        // Modern Java removed most of the old verbosity.
        var names = List.of("Ada", "Grace", "Alan");        // var: inferred, still static
        var greeting = switch (names.size()) {              // switch as an expression
            case 0 -> "nobody";
            case 1 -> "one person";
            default -> names.size() + " people";
        };
        System.out.println(greeting);

        // Text blocks: multi-line strings without escape soup.
        var json = """
            {
              "count": %d,
              "rate": %.2f
            }""".formatted(count, rate);
        System.out.println(json);
    }
}

import java.util.*;

// --- broken: equals overridden, hashCode forgotten ------------------------
class BadSku {
    final String code;
    BadSku(String code) { this.code = code; }

    @Override public boolean equals(Object o) {
        return o instanceof BadSku other && code.equals(other.code);
    }
    // No hashCode. Inherited identity hash is used instead.
}

// --- correct, by hand ------------------------------------------------------
final class Sku {
    private final String code;
    Sku(String code) { this.code = Objects.requireNonNull(code); }

    @Override public boolean equals(Object o) {
        return o instanceof Sku other && code.equals(other.code);
    }
    @Override public int hashCode() { return Objects.hash(code); }
    @Override public String toString() { return "Sku[" + code + "]"; }
}

// --- correct, and free -----------------------------------------------------
record SkuRecord(String code) { }   // equals, hashCode, toString all generated

public class Demo {
    public static void main(String[] args) {
        Map<BadSku, Integer> broken = new HashMap<>();
        broken.put(new BadSku("A-1"), 10);
        System.out.println(broken.get(new BadSku("A-1")));   // null — silently wrong

        Map<Sku, Integer> works = new HashMap<>();
        works.put(new Sku("A-1"), 10);
        System.out.println(works.get(new Sku("A-1")));       // 10

        Set<BadSku> set = new HashSet<>();
        set.add(new BadSku("A-1"));
        set.add(new BadSku("A-1"));
        System.out.println(set.size());                      // 2 — duplicates, silently

        System.out.println(new SkuRecord("A-1").equals(new SkuRecord("A-1")));  // true
    }
}

import java.util.*;

public class Collections1 {

    // Program to the interface: callers do not know or care it is an ArrayList.
    private final List<String> internal = new ArrayList<>();

    // Returning `internal` would let callers mutate our state behind our back.
    public List<String> items() { return List.copyOf(internal); }

    public void add(String item) { internal.add(item); }

    public static void main(String[] args) {
        // HashMap gives no ordering guarantee.
        Map<String, Integer> counts = new HashMap<>();
        counts.put("b", 2); counts.put("a", 1); counts.put("c", 3);

        // LinkedHashMap preserves insertion order — needed more often than expected,
        // for example when building a response the user reads top to bottom.
        Map<String, Integer> ordered = new LinkedHashMap<>();
        ordered.put("b", 2); ordered.put("a", 1); ordered.put("c", 3);
        System.out.println(ordered.keySet());     // [b, a, c] — guaranteed

        // Useful map methods that replace clumsy get/null-check/put sequences.
        Map<String, List<String>> byRegion = new HashMap<>();
        byRegion.computeIfAbsent("EMEA", k -> new ArrayList<>()).add("Acme");
        byRegion.computeIfAbsent("EMEA", k -> new ArrayList<>()).add("Contoso");

        Map<String, Integer> tally = new HashMap<>();
        tally.merge("errors", 1, Integer::sum);   // insert 1, or add 1 if present
        tally.merge("errors", 1, Integer::sum);
        System.out.println(tally);                 // {errors=2}

        // Immutable, and rejects nulls.
        List<String> regions = List.of("EMEA", "NA", "APAC");
        // regions.add("LATAM");                   // UnsupportedOperationException

        // Erasure: this is why you cannot test the type parameter at runtime.
        // if (regions instanceof List<String>) { }   // does not compile
    }
}

import java.util.*;
import java.util.stream.*;

record Order(String reference, String region, double total, boolean paid) { }

public class Streams1 {
    public static void main(String[] args) {
        List<Order> orders = loadOrders();

        // Filter, sort, project — runs only at collect().
        List<String> largeUnpaid = orders.stream()
            .filter(o -> !o.paid())
            .filter(o -> o.total() > 1_000)
            .sorted(Comparator.comparingDouble(Order::total).reversed())
            .map(Order::reference)                       // method reference
            .toList();

        // Grouping with a downstream collector: revenue per region in one expression.
        Map<String, Double> revenueByRegion = orders.stream()
            .collect(Collectors.groupingBy(Order::region,
                     Collectors.summingDouble(Order::total)));

        // Counting per region, preserving a useful order.
        Map<String, Long> countByRegion = orders.stream()
            .collect(Collectors.groupingBy(Order::region,
                     TreeMap::new,                        // sorted keys
                     Collectors.counting()));

        // --- Optional as a return type ------------------------------------
        Optional<Order> largest = orders.stream().max(Comparator.comparingDouble(Order::total));

        // Good: the absent case is handled explicitly.
        String label = largest.map(Order::reference).orElse("no orders");

        // Also good: absence is genuinely a bug here, so fail loudly with context.
        Order mustExist = largest.orElseThrow(
            () -> new IllegalStateException("no orders loaded"));

        // Bad: reintroduces exactly the failure Optional exists to prevent.
        // Order bad = largest.get();

        System.out.println(label + " " + revenueByRegion + " " + countByRegion);
    }

    static List<Order> loadOrders() {
        return List.of(new Order("A-1", "EMEA", 1500, false),
                       new Order("A-2", "EMEA",  300, true),
                       new Order("A-3", "NA",   2400, false));
    }
}

import java.io.*;
import java.nio.file.*;

public class Exceptions1 {

    // Unchecked: a null id is a programming error, not a recoverable condition.
    static void validate(String customerId) {
        if (customerId == null || customerId.isBlank())
            throw new IllegalArgumentException("customerId must not be blank");
    }

    // Checked and SPECIFIC. `throws Exception` would tell the caller nothing.
    static String readContract(Path path) throws IOException {
        // try-with-resources closes the reader even if an exception is thrown,
        // and cannot be got wrong the way a finally block can.
        try (var reader = Files.newBufferedReader(path)) {
            return reader.lines().reduce("", (a, b) -> a + "\n" + b);
        }
    }

    // Wrapping across a layer boundary — with the cause preserved.
    static String loadContract(String customerId) {
        validate(customerId);
        try {
            return readContract(Path.of("contracts", customerId + ".txt"));
        } catch (NoSuchFileException e) {
            // Specific, and genuinely recoverable: no contract on file is a real state.
            throw new ContractNotFoundException("No contract for " + customerId, e);
        } catch (IOException e) {
            // `e` as the cause keeps the original stack trace. Dropping it is
            // how a production failure becomes undiagnosable.
            throw new ContractReadException("Could not read contract for " + customerId, e);
        }
    }

    public static void main(String[] args) {
        // The construct to never write:
        // try { loadContract("C-1"); } catch (Exception e) { }
        //   -> a failure becomes a silently wrong result and the log says nothing.
        System.out.println(loadContract("C-1"));
    }
}

class ContractNotFoundException extends RuntimeException {
    ContractNotFoundException(String message, Throwable cause) { super(message, cause); }
}
class ContractReadException extends RuntimeException {
    ContractReadException(String message, Throwable cause) { super(message, cause); }
}

import java.util.List;

// One line replaces a forty-line data class.
record Customer(String id, String name, String region) {
    // Compact constructor: validation runs before the fields are assigned.
    Customer {
        if (id == null || id.isBlank())
            throw new IllegalArgumentException("id is required");
        region = region == null ? "UNKNOWN" : region.toUpperCase();   // normalise
    }
}

// A closed set of outcomes. Nobody outside this file can add a case.
sealed interface BorrowResult permits Borrowed, AlreadyOnLoan, BookNotFound { }

record Borrowed(String loanId, java.time.LocalDate dueOn) implements BorrowResult { }
record AlreadyOnLoan(java.time.LocalDate dueBack)         implements BorrowResult { }
record BookNotFound(String bookId)                        implements BorrowResult { }

public class Modern {

    // The compiler checks this switch is exhaustive. Adding a fourth
    // BorrowResult makes every switch like this one fail to compile — which
    // is exactly what you want.
    static String describe(BorrowResult result) {
        return switch (result) {
            case Borrowed(String id, var due)  -> "Borrowed " + id + ", due " + due;
            case AlreadyOnLoan(var dueBack)    -> "Already on loan until " + dueBack;
            case BookNotFound(String bookId)   -> "No such book: " + bookId;
        };
        // No `default` needed, and adding one would DISABLE the exhaustiveness
        // check — the compiler would stop telling you about the missing case.
    }

    public static void main(String[] args) {
        // Pattern matching: test and bind in one step, no cast on the next line.
        Object o = new Customer("C-1", "Acme", "emea");
        if (o instanceof Customer c && c.region().equals("EMEA"))
            System.out.println(c.name() + " is in EMEA");

        List<BorrowResult> results = List.of(
            new Borrowed("L-1", java.time.LocalDate.now().plusDays(14)),
            new BookNotFound("B-9"));

        results.forEach(r -> System.out.println(describe(r)));
    }
}

