import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import java.net.URI;

// The public contract — deliberately not the JPA entity.
record MovementRequest(
    @NotBlank(message = "sku is required") String sku,
    @Positive(message = "quantity must be greater than zero") int quantity,
    @NotNull MovementType type) { }

record StockResponse(String sku, int onHand, String lastMovementId) { }

@RestController
@RequestMapping("/api/movements")
class MovementController {

    private final InventoryService inventory;
    MovementController(InventoryService inventory) { this.inventory = inventory; }

    @PostMapping
    ResponseEntity<StockResponse> record(@Valid @RequestBody MovementRequest request) {
        // @Valid means a blank sku or a zero quantity never reaches this line;
        // the client already has a 400 naming the field.
        var result = inventory.record(request.sku(), request.quantity(), request.type());

        return ResponseEntity
            .created(URI.create("/api/stock/" + result.sku()))    // 201 + Location
            .body(new StockResponse(result.sku(), result.onHand(), result.movementId()));
    }
}

// One place for error mapping, so every controller answers the same shape.
@RestControllerAdvice
class ApiExceptionHandler {

    @ExceptionHandler(SkuNotFoundException.class)
    ProblemDetail notFound(SkuNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    // 409, not 400: the request is valid, the world is not in the right state.
    // A caller can retry this once stock arrives; retrying a 400 is pointless.
    @ExceptionHandler(InsufficientStockException.class)
    ProblemDetail conflict(InsufficientStockException e) {
        var problem = ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, e.getMessage());
        problem.setTitle("Insufficient stock");
        problem.setProperty("sku", e.sku());
        problem.setProperty("available", e.available());
        return problem;
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    ProblemDetail invalid(MethodArgumentNotValidException e) {
        var problem = ProblemDetail.forStatus(HttpStatus.BAD_REQUEST);
        problem.setTitle("Validation failed");
        // Name the offending fields; the default body is not much use to a client.
        problem.setProperty("errors", e.getBindingResult().getFieldErrors().stream()
            .collect(java.util.stream.Collectors.toMap(
                org.springframework.validation.FieldError::getField,
                f -> f.getDefaultMessage() == null ? "invalid" : f.getDefaultMessage(),
                (a, b) -> a)));
        return problem;
    }
}

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class InventoryService {

    private final StockRepository stock;
    private final MovementRepository movements;

    public InventoryService(StockRepository stock, MovementRepository movements) {
        this.stock = stock;
        this.movements = movements;
    }

    // At the SERVICE boundary: both writes commit together or neither does.
    // On the repository methods instead, this would be two transactions and a
    // failure could leave the stock updated with no movement recorded.
    @Transactional
    public MovementResult record(String sku, int quantity, MovementType type) {
        var level = stock.findBySkuForUpdate(sku)          // pessimistic lock
                         .orElseThrow(() -> new SkuNotFoundException(sku));

        int delta = type == MovementType.OUT ? -quantity : quantity;
        int updated = level.onHand() + delta;

        // The rule lives HERE, so every caller gets it and the message is readable.
        // A CHECK constraint in the database backs it up, so a race cannot bypass it —
        // but a constraint violation is not a message you want to show a user.
        if (updated < 0)
            throw new InsufficientStockException(sku, level.onHand(), quantity);

        stock.updateOnHand(sku, updated);
        var movement = movements.save(new Movement(sku, quantity, type));
        return new MovementResult(sku, updated, movement.id());
    }

    // Self-invocation trap: calling record() from here does NOT start a
    // transaction, because the proxy is bypassed on an internal call.
    public void recordBatchWrong(List<MovementRequest> batch) {
        batch.forEach(r -> record(r.sku(), r.quantity(), r.type()));   // no transaction
    }

    // Correct: put @Transactional on the entry point that should be atomic.
    @Transactional
    public void recordBatch(List<MovementRequest> batch) {
        batch.forEach(r -> record(r.sku(), r.quantity(), r.type()));
    }
}

import jakarta.persistence.*;
import org.springframework.data.jpa.repository.*;
import java.util.*;

@Entity
@Table(name = "stock_item",
       uniqueConstraints = @UniqueConstraint(columnNames = "sku"))   // natural key
public class StockItem {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)   // stable surrogate key
    private Long id;

    @Column(nullable = false, length = 64)
    private String sku;

    @Column(nullable = false)
    private int onHand;

    // Explicitly lazy. @ManyToOne defaults to EAGER, which silently joins this
    // table into every query that touches a StockItem.
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "warehouse_id")
    private Warehouse warehouse;

    protected StockItem() { }    // JPA requires a no-arg constructor
    // getters omitted
}

public interface StockRepository extends JpaRepository<StockItem, Long> {

    // Derived from the method name — readable at this size.
    Optional<StockItem> findBySku(String sku);

    // Past about three conditions the name stops being readable. Be explicit.
    @Query("""
           select s from StockItem s
           where s.onHand < :threshold
             and s.warehouse.id = :warehouseId
           order by s.onHand asc
           """)
    List<StockItem> findLowStock(int threshold, Long warehouseId);

    // Fetch join: loads the warehouse in ONE query instead of one per item.
    @Query("select s from StockItem s join fetch s.warehouse where s.onHand = 0")
    List<StockItem> findOutOfStockWithWarehouse();

    // Pessimistic lock so two concurrent movements cannot both read the same
    // balance and both decide there is enough stock.
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select s from StockItem s where s.sku = :sku")
    Optional<StockItem> findBySkuForUpdate(String sku);
}

