// --- the lost update ------------------------------------------------------
// Request A reads onHand = 1        Request B reads onHand = 1
// A checks 1 >= 1, ok               B checks 1 >= 1, ok
// A writes 0                        B writes 0
// One unit sold twice. No error anywhere.

// Defence 1: optimistic locking — good when conflicts are rare.
@Entity
public class StockItem {
    @Version
    private long version;      // every update checks this has not changed;
                               // the loser gets OptimisticLockingFailureException
}

// Defence 2: pessimistic locking — right for stock, where conflicts are common
// and retrying is awkward. The second reader waits rather than failing.
@Lock(LockModeType.PESSIMISTIC_WRITE)
@Query("select s from StockItem s where s.sku = :sku")
Optional<StockItem> findBySkuForUpdate(String sku);


-- Defence 3: the backstop. Application logic alone cannot guarantee an
-- invariant under concurrency; this makes it true regardless.
ALTER TABLE stock_item ADD CONSTRAINT ck_stock_non_negative CHECK (on_hand >= 0);

import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;

class InventoryServiceTest {

    // A fake: a real, simple implementation. Tests outcomes, survives refactors.
    static class FakeStockRepository implements StockRepository {
        private final Map<String, Integer> levels = new HashMap<>();
        void seed(String sku, int qty) { levels.put(sku, qty); }
        public Optional<StockItem> findBySkuForUpdate(String sku) {
            return Optional.ofNullable(levels.get(sku)).map(q -> new StockItem(sku, q));
        }
        public void updateOnHand(String sku, int qty) { levels.put(sku, qty); }
        int onHand(String sku) { return levels.getOrDefault(sku, 0); }
    }

    private FakeStockRepository stock;
    private InventoryService service;

    @BeforeEach
    void setUp() {
        stock = new FakeStockRepository();
        // No Spring context. Plain construction, milliseconds per test.
        service = new InventoryService(stock, new FakeMovementRepository());
    }

    @Test
    void record_whenStockAvailable_reducesBalance() {
        stock.seed("SKU-1", 10);

        service.record("SKU-1", 3, MovementType.OUT);

        assertEquals(7, stock.onHand("SKU-1"));    // the outcome, not the calls
    }

    @Test
    void record_whenQuantityExceedsStock_throwsAndWritesNothing() {
        stock.seed("SKU-1", 2);

        assertThrows(InsufficientStockException.class,
                     () -> service.record("SKU-1", 5, MovementType.OUT));

        // The rule is not only "it throws" — it is also that nothing changed.
        assertEquals(2, stock.onHand("SKU-1"));
    }

    @Test
    void record_whenQuantityExactlyMatchesStock_succeedsToZero() {
        stock.seed("SKU-1", 5);

        service.record("SKU-1", 5, MovementType.OUT);

        assertEquals(0, stock.onHand("SKU-1"));    // the boundary, easy to get wrong
    }

    @ParameterizedTest
    @ValueSource(ints = {0, -1, -100})
    void record_whenQuantityNotPositive_throws(int quantity) {
        stock.seed("SKU-1", 10);
        assertThrows(IllegalArgumentException.class,
                     () -> service.record("SKU-1", quantity, MovementType.OUT));
    }
}

import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;
