// A real Postgres, not H2. H2's dialect differs enough that queries pass in
// tests and fail in production — which defeats the purpose of the test.
@DataJpaTest
@Testcontainers
class StockRepositoryTest {

    @Container
    @ServiceConnection
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:16-alpine");

    @Autowired StockRepository repo;
    @Autowired TestEntityManager em;

    @Test
    void findLowStock_returnsOnlyItemsBelowThreshold_orderedAscending() {
        var warehouse = em.persist(new Warehouse("Main"));
        em.persist(new StockItem("SKU-1",  2, warehouse));
        em.persist(new StockItem("SKU-2", 50, warehouse));
        em.persist(new StockItem("SKU-3",  7, warehouse));
        em.flush();

        var low = repo.findLowStock(10, warehouse.getId());

        // This exercises the ACTUAL JPQL. A fake repository never would.
        assertEquals(List.of("SKU-1", "SKU-3"), low.stream().map(StockItem::getSku).toList());
    }

    @Test
    void checkConstraint_rejectsNegativeStock() {
        var warehouse = em.persist(new Warehouse("Main"));
        em.persist(new StockItem("SKU-1", 5, warehouse));
        em.flush();

        // The database backstop, verified against the real database.
        assertThrows(DataIntegrityViolationException.class, () -> {
            repo.updateOnHand("SKU-1", -1);
            em.flush();
        });
    }
}

