import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.ConcurrentHashMap;

// --- broken: shared mutable state in a singleton bean --------------------
@Service
public class BadMetricsService {
    private long requestCount;                    // shared by every request
    private Map<String, Integer> byEndpoint = new HashMap<>();   // not thread-safe

    public void record(String endpoint) {
        requestCount++;                           // read-modify-write: updates lost
        byEndpoint.merge(endpoint, 1, Integer::sum);  // HashMap can corrupt under
                                                      // concurrent writes — including
                                                      // infinite loops on resize
    }
}

// --- correct --------------------------------------------------------------
@Service
public class MetricsService {
    private final AtomicLong requestCount = new AtomicLong();
    private final ConcurrentHashMap<String, AtomicLong> byEndpoint = new ConcurrentHashMap<>();

    public void record(String endpoint) {
        requestCount.incrementAndGet();           // atomic, lock-free

        // computeIfAbsent is atomic. A get-then-put would not be: two threads
        // could both find null and both create a counter, losing one.
        byEndpoint.computeIfAbsent(endpoint, k -> new AtomicLong()).incrementAndGet();
    }

    public long total() { return requestCount.get(); }
}

// --- best: no shared state at all ----------------------------------------
@Service
public class StatelessInventoryService {
    private final StockRepository stock;      // final, and itself stateless

    public StatelessInventoryService(StockRepository stock) { this.stock = stock; }

    // Everything this method needs is a parameter, a local, or in the database.
    // There is nothing for two threads to contend over inside this object.
    public int available(String sku) {
        return stock.findBySku(sku).map(StockItem::getOnHand).orElse(0);
    }
}

