public class InventoryReadinessIndicator implements HealthIndicator {

    private final StockRepository stock;
    private final FlywayMigrationChecker migrations;

    public InventoryReadinessIndicator(StockRepository stock, FlywayMigrationChecker migrations) {
        this.stock = stock;
        this.migrations = migrations;
    }

    @Override
    public Health health() {
        if (!migrations.allApplied())
            // Alive, but must NOT receive traffic: the schema is not current.
            return Health.outOfService().withDetail("reason", "pending migrations").build();
        try {
            stock.count();
            return Health.up().build();
        } catch (Exception e) {
            return Health.down().withDetail("reason", "database unreachable").build();
        }
    }
}

// Correlation id in every log line, so one id retrieves the whole request.
@Component
public class CorrelationIdFilter extends OncePerRequestFilter {
    @Override
    protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res,
                                    FilterChain chain) throws ServletException, IOException {
        var id = Optional.ofNullable(req.getHeader("X-Correlation-Id"))
                         .orElseGet(() -> UUID.randomUUID().toString().substring(0, 8));
        MDC.put("correlationId", id);
        res.setHeader("X-Correlation-Id", id);     // the client can quote it back
        try { chain.doFilter(req, res); } finally { MDC.remove("correlationId"); }
    }
}

